int[] arr = {10, 20, 30, 40, 50};
int sum = 0;
for (int i = 1; i < arr.length; i += 2) {
    sum += arr[i];
}
System.out.println(sum);

int[][] m = {{1, 2, 3}, {4, 5, 6}};
int total = 0;
for (int r = 0; r < m.length; r++) {
    for (int c = 0; c < m[r].length; c++) {
        if ((r + c) % 2 == 0) total += m[r][c];
    }
}
System.out.println(total);
